style.css:
@-moz-document domain("roblox.com") {
/* ==========================================
       1) 450'lik Paket İçin -> Standart Builders Club (BC)
       ========================================== */
    [class*="premium-tier-450"] .icon-premium-medium,
    [class*="premium-tier-450"] .icon-premium-small,
    [class*="premium-tier-450"] .premium-icon,
    [class*="tier1"] .icon-premium-medium {
        background-image: url("https://rbxcdn.com") !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
    }

    /* ==========================================
       2) 1000'lik Paket İçin -> Turbo Builders Club (TBC)
       ========================================== */
    [class*="premium-tier-1000"] .icon-premium-medium,
    [class*="premium-tier-1000"] .icon-premium-small,
    [class*="premium-tier-1000"] .premium-icon,
    [class*="tier2"] .icon-premium-medium {
        background-image: url("https://rbxcdn.com") !important; /* TBC Logosu */
        background-size: contain !important;
        background-repeat: no-repeat !important;
    }

    /* ==========================================
       3) 2200'lük Paket İçin -> Outrageous Builders Club (OBC / Sizin deyiminizle 2000'lik)
       ========================================== */
    [class*="premium-tier-2200"] .icon-premium-medium,
    [class*="premium-tier-2200"] .icon-premium-small,
    [class*="premium-tier-2200"] .premium-icon,
    [class*="tier3"] .icon-premium-medium {
        background-image: url("https://rbxcdn.com") !important; /* OBC Logosu */
        background-size: contain !important;
        background-repeat: no-repeat !important;
    }

    /* Genel logo boyutu sabitleme */
    .icon-premium-medium, .icon-premium-small, .premium-icon {
        background-position: center !important;
        width: 20px !important;
        height: 20px !important;
    }
}
